// Runtime for the C code generated by xlat/ (build/gen_image.py).
//
// Model (the same one XenonRecomp/N64Recomp use, adapted to x86_64 SysV):
//   * every original function becomes `void F_<addr>(rc_ctx *c)`;
//   * guest registers live in rc_ctx between functions and in C locals inside
//     one (so clang allocates them to arm64 registers and drops dead flags);
//   * guest memory is host memory: the original image is mapped at
//     rc_slide + vmaddr, and guest pointers are host pointers;
//   * the guest stack is a host buffer; call/ret push and pop the original
//     return addresses so frames look exactly like on x86;
//   * imports are called natively (one thunk per import, see thunks/gen_thunks.py).
#ifndef RC_H
#define RC_H

#include <stdint.h>
#include <string.h>

typedef struct {
  uint64_t lo, hi;
} rc_v128;

typedef struct rc_ctx {
  uint64_t r[16];  // rax rcx rdx rbx rsp rbp rsi rdi r8..r15 (x86 encoding order)
  rc_v128 x[16];
  uint32_t mxcsr;
  // Runtime-private (not a guest register): native frame of the thread's newest live native->guest
  // call, ~0 if none. A thunk whose frame is at or below it can skip rc_unwind_sync (rc_call.h,
  // rc_unwind_guard); kept by runtime/rc_thread.c and rc_setjmp.c.
  uint64_t cg_fp;
} rc_ctx;

typedef void (*rc_fn)(rc_ctx *);

extern uint64_t rc_slide;  // host address of vmaddr 0 (image base - 0x100000000 + slide)
#define RC_A(vmaddr) (rc_slide + (uint64_t)(vmaddr))

// Unaligned, strict-aliasing-safe memory access (x86 allows unaligned access
// everywhere; arm64 does too for normal loads/stores, so these compile to
// plain ldr/str).
//
// -DRC_MO_TSO keeps x86's total store order in a translation unit: every guest
// load is followed by a load fence (dmb ishld: orders it before later loads and
// stores) and every guest store is preceded by a store fence (dmb ishst: orders
// earlier stores before it). That is load->load, load->store and store->store,
// what TSO guarantees (store->load is not). Fences rather than ldapr/stlr,
// because those fault on unaligned addresses.
// RC_LDS / RC_STS are accesses the translator knows to be on the thread's own
// stack (rsp-based operands, rbp-based ones in functions that keep rbp as the
// frame pointer, push/pop, return addresses): never fenced. Data
// handed to another thread through the stack goes through pthread primitives,
// which order memory themselves.
#define RC_LDS(T, a) ({ T _v; memcpy(&_v, (const void *)(uintptr_t)(a), sizeof _v); _v; })
#define RC_STS(T, a, v) do { T _v = (T)(v); memcpy((void *)(uintptr_t)(a), &_v, sizeof _v); } while (0)
#ifdef RC_MO_TSO
#if defined(__aarch64__)
#define RC_FENCE_LD() __asm__ volatile("dmb ishld" ::: "memory")
#define RC_FENCE_ST() __asm__ volatile("dmb ishst" ::: "memory")
#else
#define RC_FENCE_LD() __atomic_thread_fence(__ATOMIC_ACQUIRE)
#define RC_FENCE_ST() __atomic_thread_fence(__ATOMIC_RELEASE)
#endif
#define RC_LD(T, a) ({ T _v; memcpy(&_v, (const void *)(uintptr_t)(a), sizeof _v); \
  RC_FENCE_LD(); _v; })
#define RC_ST(T, a, v) do { T _v = (T)(v); RC_FENCE_ST(); \
  memcpy((void *)(uintptr_t)(a), &_v, sizeof _v); } while (0)
#else
#define RC_LD(T, a) ({ T _v; memcpy(&_v, (const void *)(uintptr_t)(a), sizeof _v); _v; })
#define RC_ST(T, a, v) do { T _v = (T)(v); memcpy((void *)(uintptr_t)(a), &_v, sizeof _v); } while (0)
#endif

// Indirect call/jump dispatch: guest address -> translated function.
rc_fn rc_lookup(uint64_t host_addr);
_Noreturn void rc_fail(const char *what, uint64_t addr);
//
// rc_icall is inlined at every indirect call site (one indirect branch per site, for the branch
// predictor): one load from rc_disp, a direct-mapped table built by rc_image_load (runtime/rc_image.c
// has the entry format). Everything it does not resolve (native targets, the few functions that
// share 16 bytes with another, no function at all) goes to rc_icall_slow. Read-only after the image
// is loaded: plain loads, no TSO fences.
typedef struct {
  uint64_t lo;          // host address of entry 0's 16 bytes
  uint64_t n;           // entries (0: not built, everything takes the slow path)
  const uint32_t *tab;
  uint64_t fbase;       // host address entries' function offsets are relative to
} rc_disp_t;
extern rc_disp_t rc_disp;
static inline rc_fn rc_lookup_fast(uint64_t host) {
  uint64_t i = (host - rc_disp.lo) >> 4;
  if (__builtin_expect(i < rc_disp.n, 1)) {
    uint32_t e = rc_disp.tab[i];
    if (__builtin_expect((e >> 27) == (16 | (host & 15)), 1))
      return (rc_fn)(rc_disp.fbase + ((uint64_t)(e & 0x7ffffff) << 2));
  }
  return 0;
}
void rc_icall_slow(rc_ctx *c, uint64_t host_addr);
__attribute__((always_inline)) static inline void rc_icall(rc_ctx *c, uint64_t host_addr) {
  uint64_t i = (host_addr - rc_disp.lo) >> 4;
  if (__builtin_expect(i < rc_disp.n, 1)) {
    uint32_t e = rc_disp.tab[i];
    if (__builtin_expect((e >> 27) == (16 | (host_addr & 15)), 1)) {
      ((rc_fn)(rc_disp.fbase + ((uint64_t)(e & 0x7ffffff) << 2)))(c);
      return;
    }
  }
  rc_icall_slow(c, host_addr);
}
// rc_la_bound[k]: the native address rc_image_load bound __la_symbol_ptr slot k to (~0 if it is
// unbound, inside the image, or k >= RC_LA_MAX). A `call/jmp [rip+slot]` whose target still equals
// it is the slot's import thunk I_<slot>, which is what rc_icall_native would pick
// (xlat/calls.py: emit_slot_call).
#define RC_LA_MAX 4096
extern uint64_t rc_la_bound[RC_LA_MAX];

// --- Runtime interfaces
//
// Image (runtime/rc_image.c): map, rebase, bind; 0 on success.
int rc_image_load(const char *path);
//
// Threads (runtime/rc_thread.c): the calling thread's context, with its
// own guest stack, created on first use (native threads entering guest code).
rc_ctx *rc_thread_ctx(void);
//
// Native -> guest (runtime/rc_tramp.*): a native-callable function
// pointer that runs the guest function at host address guest_fn with the
// native arguments (integer args in x0..x7 -> rdi rsi rdx rcx r8 r9 + guest
// stack, FP args in d0..d7 -> xmm0..7; returns rax in x0 and xmm0 in d0).
// Pointers outside the image are returned unchanged.
void *rc_tramp_get(uint64_t guest_fn);
//
// Guest -> native (runtime/rc_native.*): call a native function with
// x0..x7 = ix[0..7] and d0..d7 = dx[0..7] (low 64 bits of each xmm); ret
// receives x0, x1, d0, d1. Covers every non-variadic C function whose
// arguments are integers, pointers, floats and doubles (both ABIs classify
// integer and FP arguments separately); generated thunks handle the rest.
void rc_native_call(uint64_t fn, const uint64_t ix[8], const uint64_t dx[8], uint64_t ret[4]);
// rc_icall's branch for targets outside the image (an import stored as a
// pointer, a native callback): marshals rdi..r9/xmm0..7 (+ guest stack) with
// rc_native_call, sets rax/rdx/xmm0/xmm1 and pops the return address.
void rc_icall_native(rc_ctx *c, uint64_t host);
//
// Imports: a call through __stubs is `I_<slot vmaddr>(rc_ctx *)`, generated
// per import by tools/ws7/recomp/thunks.

// x86 float->int conversion semantics: out of range or NaN gives the
// "integer indefinite" value (INT_MIN), where arm64 fcvtzs saturates.
static inline int32_t rc_cvtt_f64_i32(double d) {
  return (d > -2147483649.0 && d < 2147483648.0) ? (int32_t)d : INT32_MIN;
}
static inline int64_t rc_cvtt_f64_i64(double d) {
  return (d >= -9223372036854775808.0 && d < 9223372036854775808.0) ? (int64_t)d : INT64_MIN;
}
static inline int32_t rc_cvtt_f32_i32(float f) { return rc_cvtt_f64_i32((double)f); }
static inline int64_t rc_cvtt_f32_i64(float f) { return rc_cvtt_f64_i64((double)f); }
// x86 minss/maxss: return the second operand unless the comparison is true
// (so NaN in either operand, or +-0 pairs, give the second operand).
static inline float rc_minf(float a, float b) { return a < b ? a : b; }
static inline float rc_maxf(float a, float b) { return a > b ? a : b; }
static inline double rc_mind(double a, double b) { return a < b ? a : b; }
static inline double rc_maxd(double a, double b) { return a > b ? a : b; }

static inline float rc_f32(uint32_t u) { float f; memcpy(&f, &u, 4); return f; }
static inline uint32_t rc_u32f(float f) { uint32_t u; memcpy(&u, &f, 4); return u; }
static inline double rc_f64(uint64_t u) { double f; memcpy(&f, &u, 8); return f; }
static inline uint64_t rc_u64f(double f) { uint64_t u; memcpy(&u, &f, 8); return u; }

static inline uint8_t rc_parity(uint64_t v) { return !__builtin_parity((unsigned)(v & 0xff)); }

#endif
